// DOCUMENTS: the Stage 6 component — an authoritative name table with a
// tick-TTL resolver ledger, mirroring the Cache's Map-lookup pattern. A
// lookup consults the authoritative table only on a cache miss or an
// expired entry; a hit inside ttlTicks is an incrementing `cachedHits`
// with no authoritative consult. Deterministic by construction: no clock,
// no RNG — time arrives as the `currentTick` argument.
//
// CHECKS: the constructor rejects an address that is not a two-number
// mini-IP and a ttlTicks that is not a positive integer (fail-loud over
// silent mis-configuration), and an expired ledger entry is evicted before
// the answer is produced, so it can never be served from the ledger.
export function createDns({ address = '10.60', ttlTicks = 300 } = {}) {
  if (!/^\d+\.\d+$/.test(address)) {
    throw new Error(`dns: invalid mini-IP address ${address}`);
  }
  if (!Number.isInteger(ttlTicks) || ttlTicks < 1) {
    throw new Error(`dns: ttlTicks must be a positive integer, got ${ttlTicks}`);
  }
  // The authoritative table: name -> mini-IP. Stage 6b adds a CDN name.
  const records = new Map([['example.com', '10.1']]);
  const cache = new Map(); // name -> { name, target, expiresAtTick }
  let lookups = 0;
  let cachedHits = 0;
  let authoritative = 0;
  let lastLookup = null;

  // A ledger entry is stale the moment the current tick reaches its
  // expiry: resolved at tick T with ttlTicks = 300 lives through T + 299.
  function evictExpired(currentTick = 0) {
    for (const entry of cache.values()) {
      if (currentTick >= entry.expiresAtTick) cache.delete(entry.name);
    }
  }

  function lookup(name, currentTick = 0) {
    evictExpired(currentTick);
    lookups += 1;
    const entry = cache.get(name);
    if (entry) {
      cachedHits += 1;
      lastLookup = { name, status: 'HIT', target: entry.target, atTick: currentTick };
      return entry.target;
    }
    authoritative += 1;
    const target = records.get(name) ?? null;
    if (target === null) {
      lastLookup = { name, status: 'NX', target: null, atTick: currentTick };
      // CHECKS: an unknown name is an answer, not a crash — the browser
      // renders the NX card and no GET leaves it.
      return { status: 'NX' };
    }
    cache.set(name, { name, target, expiresAtTick: currentTick + ttlTicks });
    lastLookup = { name, status: 'MISS', target, atTick: currentTick };
    return target;
  }

  function snapshot(currentTick = 0) {
    evictExpired(currentTick);
    return {
      address,
      ttlTicks,
      lookups,
      cachedHits,
      authoritative,
      lastLookup,
      entries: [...cache.values()].map((e) => ({
        name: e.name,
        target: e.target,
        expiresAtTick: e.expiresAtTick,
        ttlRemaining: e.expiresAtTick - currentTick,
      })),
    };
  }

  return {
    get address() {
      return address;
    },
    evictExpired,
    lookup,
    snapshot,
  };
}

// DOCUMENTS: the Stage 6 component — a cross-subnet Router joining the
// `10.x` and `20.x` network instances at two interface addresses
// (leftAddress `10.65`, rightAddress `20.1`). Any cross-subnet frame takes
// exactly one router hop (the `routed` counter); same-subnet sends stay on
// the plain network send/deliverToQueue contract untouched. Subnet 20
// holds the router's own interface in 6a — stage 6b occupies `20.1` with
// the CDN edge — so an unregistered `20.x` host fails loud through the
// destination network's own resolution.
//
// CHECKS: the constructor rejects a non two-number mini-IP on either
// interface and a configuration whose two interfaces share one subnet.
export function createRouter({ leftAddress = '10.65', rightAddress = '20.1' } = {}) {
  if (!/^\d+\.\d+$/.test(leftAddress)) {
    throw new Error(`router: invalid mini-IP address ${leftAddress}`);
  }
  if (!/^\d+\.\d+$/.test(rightAddress)) {
    throw new Error(`router: invalid mini-IP address ${rightAddress}`);
  }
  const netOf = (addr) => String(addr).split('.')[0];
  if (netOf(leftAddress) === netOf(rightAddress)) {
    throw new Error(
      `router: interfaces must sit on different subnets, got ${leftAddress} and ${rightAddress}`,
    );
  }
  let leftNetwork = null;
  let rightNetwork = null;
  let routed = 0;

  // The engine wires both network instances in once, after construction.
  function join({ left, right }) {
    if (!left || !right) throw new Error('router: join needs both network instances');
    leftNetwork = left;
    rightNetwork = right;
  }

  function networkFor(to) {
    if (!leftNetwork || !rightNetwork) {
      throw new Error('router: no networks attached');
    }
    return netOf(to) === netOf(rightAddress) ? rightNetwork : leftNetwork;
  }

  function forward({ from, to, request }) {
    routed += 1;
    const net = networkFor(to);
    const exitFrom = netOf(to) === netOf(rightAddress) ? leftAddress : rightAddress;
    return net.send({ from: exitFrom, to, request });
  }

  // `isYou` rides through untouched, like the plain network's queue path.
  function forwardQueue({ id, from, to, request, atTick, isYou = false }) {
    routed += 1;
    const net = networkFor(to);
    const exitFrom = netOf(to) === netOf(rightAddress) ? leftAddress : rightAddress;
    net.deliverToQueue({ id, from: exitFrom, to, request, atTick, isYou });
  }

  // CHECKS: the router's 20-side interface is the endpoint itself in 6a —
  // it answers a direct frame as the interface, not as an HTTP service.
  function handleRequest() {
    return `200 Router ${rightAddress}`;
  }

  return {
    get address() {
      return leftAddress;
    },
    get rightAddress() {
      return rightAddress;
    },
    join,
    forward,
    forwardQueue,
    handleRequest,
    snapshot() {
      return { leftAddress, rightAddress, routed };
    },
  };
}

// DOCUMENTS: the network — the wiring that lets two-number mini-IP
// addressable components exchange messages. Today it carries slim HTTP
// requests to a registered server; later stages attach more components
// without changing the send/enqueue contract.
//
// Stage 6: a cross-subnet Router can be attached (`attachRouter`). When a
// frame's destination sits on a different subnet than its origin and is
// not registered locally, the frame hands off to the router for exactly
// one hop; the destination network's own resolution still decides whether
// the host exists, so unregistered cross-subnet hosts fail loud the same
// way local ones do. Same-subnet sends are untouched.
//
// CHECKS: every address crossing the wire is validated as a two-number
// mini-IP (<net>.<host>), and sends to unregistered hosts fail loud.
const MINI_IP = /^\d+\.\d+$/;

export function createNetwork() {
  const servers = new Map();
  let router = null;

  function validate(addr) {
    if (!MINI_IP.test(addr)) {
      throw new Error(`network: invalid mini-IP address ${addr}`);
    }
  }

  function resolve(address) {
    validate(address);
    const server = servers.get(address);
    if (!server) {
      throw new Error(`network: no server at ${address}`);
    }
    return server;
  }

  // CHECKS: the cross-subnet branch fires only when the destination is
  // absent locally AND sits on another subnet — a plain unknown host on
  // the local subnet still throws, exactly as it did before Stage 6.
  function crossSubnet(from, to) {
    return (
      router !== null && !servers.has(to) && String(from).split('.')[0] !== String(to).split('.')[0]
    );
  }

  return {
    registerServer(address, server) {
      validate(address);
      servers.set(address, server);
    },

    resolve,

    attachRouter(crossRouter) {
      router = crossRouter;
    },

    send({ from, to, request }) {
      validate(from);
      if (crossSubnet(from, to)) return router.forward({ from, to, request });
      const server = resolve(to);
      const response = server.handleRequest(request);
      return { from, to, request, response };
    },

    // `isYou` rides through untouched: the engine marks the learner's own
    // interactive-browser request, the server stores it on the queue row.
    deliverToQueue({ id, from, to, request, atTick, isYou = false }) {
      validate(from);
      if (crossSubnet(from, to)) {
        router.forwardQueue({ id, from, to, request, atTick, isYou });
        return;
      }
      const server = resolve(to);
      server.enqueue({ id, from, to, request, atTick, isYou });
    },
  };
}

