// DOCUMENTS: hop ownership map — which node card executes each trace hop
// and which wire lane carries it, per stage and trace shape. Pure mapping:
// snapshots in, { cardId, laneId } out (render-stage.js applies the DOM
// classes). Split from render-stage.js by responsibility
// (guard-file-size): this module owns the per-stage hop tables; that
// module owns the DOM writes.
//
// Stage 1 is emit / route / serve / render; Stage 2 inserts the LB's
// round-robin pick; Stage 3 splits the backend serve into the cache
// lookup (Cache 10.20 answers) and the response emission; Stage 4 adds
// the database hop; Stage 5 adds async worker queue processing. Stage 6
// branches on host syntax: a hosted path spends hops 2-3 on DNS 10.60
// (ask, then the answer naming the resolved target) before the stage-5
// chain, a host-less path reuses the stage-5 tables, and an NX answer
// keeps the whole trace on DNS.
export function hopTarget(snapshot) {
  const hop = snapshot.trace?.hop ?? 0;
  if (snapshot.stage === 6 && snapshot.trace?.hosted) {
    const t = snapshot.trace;
    const backendCard = t.targetServer === '10.12' ? 'node-webserver-2' : 'node-webserver';
    const dbLane = t.dbOp === 'WRITE' ? 'packet-req-db' : 'packet-res-db';
    if (t.dnsStatus === 'NX') {
      const owners = { 1: 'node-browser', 2: 'node-dns', 3: 'node-dns' };
      const lanes = {
        1: 'packet-req-left',
        2: 'packet-req-dns',
        3: 'packet-res-dns',
      };
      return { cardId: owners[hop] ?? 'node-dns', laneId: lanes[hop] ?? 'packet-req-dns' };
    }
    const owners = t.asyncJob
      ? {
          1: 'node-browser',
          2: 'node-dns',
          3: 'node-dns',
          4: 'node-network',
          5: 'node-lb',
          6: 'node-queue',
          7: backendCard,
          8: 'node-network',
          9: 'node-browser',
          10: 'node-worker',
        }
      : {
          1: 'node-browser',
          2: 'node-dns',
          3: 'node-dns',
          4: 'node-network',
          5: 'node-lb',
          6: 'node-db',
          7: backendCard,
          8: 'node-network',
          9: 'node-browser',
          10: 'node-worker',
        };
    const lanes = t.asyncJob
      ? {
          1: 'packet-req-left',
          2: 'packet-req-dns',
          3: 'packet-res-dns',
          4: 'packet-req-right',
          5: 'packet-req-lb',
          6: 'packet-req-queue',
          7: 'packet-res-cache',
          8: 'packet-res-right',
          9: 'packet-res-left',
          10: 'packet-res-db',
        }
      : {
          1: 'packet-req-left',
          2: 'packet-req-dns',
          3: 'packet-res-dns',
          4: 'packet-req-right',
          5: 'packet-req-lb',
          6: dbLane,
          7: 'packet-res-cache',
          8: 'packet-res-right',
          9: 'packet-res-left',
          10: 'packet-res-worker',
        };
