import { describe, it, expect } from 'vitest';
import { createDns } from '../../js/sim/dns.js';
import { createEngine } from '../../js/sim/engine.js';

describe('createDns', () => {
  // PINS: the TTL branch — a hit inside ttlTicks is an incrementing
  // cachedHits with no authoritative consult, and an expired entry is
  // evicted before the answer is produced, so it can never be answered
  // from the ledger (named counter-example below).
  it('resolves example.com to 10.1 and consults the authoritative table only on miss or expiry', () => {
    const dns = createDns({ address: '10.60', ttlTicks: 300 });

    // Cold lookup: the authoritative table answers and the ledger fills.
    expect(dns.lookup('example.com', 1)).toBe('10.1');
    let snap = dns.snapshot(1);
    expect(snap).toMatchObject({
      address: '10.60',
      ttlTicks: 300,
      lookups: 1,
      cachedHits: 0,
      authoritative: 1,
    });
    expect(snap.entries).toEqual([
      { name: 'example.com', target: '10.1', expiresAtTick: 301, ttlRemaining: 300 },
    ]);
    expect(dns.lastLookup).toEqual({
      name: 'example.com',
      status: 'MISS',
      target: '10.1',
      atTick: 1,
    });

    // Hit inside ttlTicks: cachedHits climbs, the authoritative count does
    // not move — the table is not consulted.
    expect(dns.lookup('example.com', 150)).toBe('10.1');
    expect(dns.lookup('example.com', 300)).toBe('10.1');
    snap = dns.snapshot(300);
    expect(snap).toMatchObject({ lookups: 3, cachedHits: 2, authoritative: 1 });
    expect(dns.lastLookup.status).toBe('HIT');

    // Named counter-example: the entry expired at tick 301 — the lookup
    // evicts it (the ledger is empty) and answers from a fresh
    // authoritative consult, never from the expired ledger row.
    expect(dns.lookup('example.com', 301)).toBe('10.1');
    snap = dns.snapshot(301);
    expect(snap).toMatchObject({ lookups: 4, cachedHits: 2, authoritative: 2 });
    expect(snap.entries).toEqual([
      { name: 'example.com', target: '10.1', expiresAtTick: 601, ttlRemaining: 300 },
    ]);
    expect(dns.lastLookup.status).toBe('MISS');

    // CHECKS: the constructor rejects a non-mini-IP address and a
    // non-positive or non-integer ttlTicks (fail-loud over misconfig).
    expect(() => createDns({ address: '1060' })).toThrow(/invalid mini-IP/);
    expect(() => createDns({ ttlTicks: 0 })).toThrow(/ttlTicks/);
    expect(() => createDns({ ttlTicks: 1.5 })).toThrow(/ttlTicks/);
  });

  // PINS: the NX branch — an unknown name is an answer object, not a
  // throw, and it never enters the ledger (the browser renders the NX
  // card; the throw rule belongs to cross-subnet addresses).
  it('answers unknown names with NX without a throw and leaves the ledger empty', () => {
    const dns = createDns();
    expect(() => dns.lookup('nope.example', 0)).not.toThrow();
    expect(dns.lookup('nope.example', 0)).toEqual({ status: 'NX' });
    expect(dns.lastLookup).toEqual({
      name: 'nope.example',
      status: 'NX',
      target: null,
      atTick: 0,
    });
    const snap = dns.snapshot(0);
    expect(snap).toMatchObject({ lookups: 2, cachedHits: 0, authoritative: 2 });
    expect(snap.entries).toEqual([]);
  });
});

describe('stage 6 dns wiring', () => {
  // PINS: the engine instantiates DNS 10.60 from stage 6 on and exposes it
  // on the snapshot; a hosted trace consumes the real ledger while a
  // host-less path (GET /about) leaves the ledger untouched.
  it('exposes DNS 10.60 on the snapshot and hosted traces consume the ledger', () => {
    const engine = createEngine({ stage: 6 });
    let snap = engine.snapshot();
    expect(snap.dns).not.toBe(null);
    expect(snap.dns.address).toBe('10.60');
    expect(snap.dns.ttlTicks).toBe(300);

    for (let hop = 0; hop < 10; hop++) {
      engine.traceHop({ method: 'GET', path: 'example.com/about' });
    }
    snap = engine.snapshot();
    expect(snap.trace.hop).toBe(10);
    expect(snap.trace.dnsStatus).toBe('MISS');
    expect(snap.trace.dnsTarget).toBe('10.1');
    expect(snap.dns).toMatchObject({ lookups: 1, cachedHits: 0, authoritative: 1 });
    expect(snap.browserDisplay.body).toBe('This is the about page');

    for (let hop = 0; hop < 10; hop++) {
      engine.traceHop({ method: 'GET', path: 'example.com/about' });
    }
    snap = engine.snapshot();
    expect(snap.trace.dnsStatus).toBe('HIT');
    expect(snap.dns).toMatchObject({ lookups: 2, cachedHits: 1, authoritative: 1 });

    // The host-less path skips DNS entirely: the ledger counters do not move.
    for (let hop = 0; hop < 8; hop++) {
      engine.traceHop({ method: 'GET', path: '/about' });
    }
    snap = engine.snapshot();
    expect(snap.trace.hop).toBe(8);
    expect(snap.trace.hosted).toBe(false);
    expect(snap.dns).toMatchObject({ lookups: 2, cachedHits: 1, authoritative: 1 });

    // Stages 1-5 expose no DNS at all.
    expect(createEngine({ stage: 5 }).snapshot().dns).toBe(null);
    expect(createEngine({ stage: 1 }).snapshot().dns).toBe(null);
  });
});

import { describe, it, expect } from 'vitest';
import { createNetwork } from '../../js/sim/network.js';
import { createRouter } from '../../js/sim/router.js';
import { createWebServer } from '../../js/sim/webserver.js';
import { createEngine } from '../../js/sim/engine.js';

describe('createRouter', () => {
  // PINS: the cross-subnet branch — a frame into subnet 20 takes exactly
  // one router hop (routed +1) through the destination network's own
  // resolution, an unregistered 20.x host (20.9) fails loud, and
  // same-subnet sends stay on the plain contract with routed untouched.
  it('forwards cross-subnet sends through exactly one router hop and fails loud on unregistered 20.x hosts', () => {
    const left = createNetwork();
    const right = createNetwork();
    const router = createRouter({ leftAddress: '10.65', rightAddress: '20.1' });
    router.join({ left, right });
    left.attachRouter(router);
    right.registerServer('20.1', router);
    const server = createWebServer({ address: '10.1' });
    left.registerServer('10.1', server);

    // Same-subnet passthrough is unchanged: the plain send resolves
    // locally and the router's counter does not move.
    expect(left.send({ from: '10.2', to: '10.1', request: 'GET /' })).toEqual({
      from: '10.2',
      to: '10.1',
      request: 'GET /',
      response: '200 Welcome to the home page',
    });
    expect(router.snapshot()).toEqual({ leftAddress: '10.65', rightAddress: '20.1', routed: 0 });

    // Cross-subnet: exactly one hop, answered by the router's own 20-side
    // interface — the only endpoint subnet 20 holds in 6a.
    expect(left.send({ from: '10.2', to: '20.1', request: 'GET /' })).toEqual({
      from: '10.2',
      to: '20.1',
      request: 'GET /',
      response: '200 Router 20.1',
    });
    expect(router.snapshot().routed).toBe(1);

    // CHECKS: an unregistered 20.x host throws through the destination
    // network's resolution (DL-1 fail-loud, mirroring local unknowns).
    expect(() => left.send({ from: '10.2', to: '20.9', request: 'GET /' })).toThrow(
      /no server at 20\.9/,
    );
    expect(() =>
      left.deliverToQueue({ id: '1:0', from: '10.2', to: '20.9', request: 'GET /', atTick: 1 }),
    ).toThrow(/no server at 20\.9/);
    // The failed hop was never counted: the frame died in resolution.
    expect(router.snapshot().routed).toBe(1);

    // A network without an attached router keeps the old fail-loud shape.
    const detached = createNetwork();
    detached.registerServer('10.1', server);
    expect(() => detached.send({ from: '10.2', to: '20.1', request: 'GET /' })).toThrow(
      /no server at 20\.1/,
    );

    // CHECKS: the constructor rejects a non-mini-IP interface and a
    // same-subnet pair.
    expect(() => createRouter({ leftAddress: '1065' })).toThrow(/invalid mini-IP/);
    expect(() => createRouter({ rightAddress: '20' })).toThrow(/invalid mini-IP/);
    expect(() => createRouter({ leftAddress: '10.65', rightAddress: '10.66' })).toThrow(
      /different subnets/,
    );
    expect(() => createRouter().forward({ from: '10.2', to: '20.1', request: 'GET /' })).toThrow(
      /no networks attached/,
    );
  });

  // PINS: the engine joins subnet 20 through the router from stage 6 on
  // and exposes the routed counter on the snapshot; stages 1-5 expose none.
  it('stage 6 engine joins subnet 20 through the router and exposes routed counters', () => {
    const engine = createEngine({ stage: 6 });
    const snap = engine.snapshot();
    expect(snap.router).toEqual({ leftAddress: '10.65', rightAddress: '20.1', routed: 0 });

    // Crowd ticks are same-subnet (10.x -> 10.1): the router stays idle.
    engine.step();
    engine.step();
    expect(engine.snapshot().router.routed).toBe(0);
    expect(engine.snapshot().served).toBeGreaterThan(0);

    expect(createEngine({ stage: 5 }).snapshot().router).toBe(null);
    expect(createEngine({ stage: 1 }).snapshot().router).toBe(null);
  });
});

import { describe, it, expect } from 'vitest';
import { describeSnapshot } from '../../js/panel/model.js';
import { componentTitle, formatComponentState } from '../../js/panel/inspector-state.js';
import { computeStageLayout } from '../../js/panel/layout.js';
import { createEngine } from '../../js/sim/engine.js';

// Stage-boundary extraction (guard-file-size): the Stage 6 narrative
// branches are pinned here — the counter-example pins the host-less story
// byte-identical to Stage 5, the hosted path adds exactly two DNS hops,
// and the NX path never emits a GET.
describe('describeSnapshot — Stage 6 traces', () => {
  const base = (trace) => ({
    stage: 6,
    tick: 2,
    users: 5,
    serverAddress: '10.1',
    queueDepth: 0,
    served: 1,
    avgLatencyTicks: 1,
    loadBalancer: { address: '10.1', nextBackend: '10.11', perBackend: {} },
    cache: { address: '10.20', ttlTicks: 10, hits: 0, misses: 1, entries: [] },
    database: {
      primaryAddress: '10.30',
      replicaAddress: '10.31',
      replicationLagTicks: 3,
      rows: [],
    },
    workerQueue: { address: '10.40', workerAddress: '10.41', pendingJobs: [] },
    dns: {
      address: '10.60',
      ttlTicks: 300,
      lookups: 1,
      cachedHits: 0,
      authoritative: 1,
      entries: [],
    },
    router: { leftAddress: '10.65', rightAddress: '20.1', routed: 0 },
    trace,
  });

  const syncTrace = {
    hop: 6,
    method: 'GET',
    path: '/about',
    request: 'GET /about',
    targetServer: '10.11',
    cacheStatus: 'MISS',
    dbOp: 'SELECT',
    dbStale: false,
    asyncJob: false,
    response: '200 This is the about page',
    status: 200,
    body: 'This is the about page',
    routeId: 'about',
  };

  it('keeps the host-less GET /about story byte-identical to Stage 5', () => {
    // CHECKS: the named counter-example — the same trace shape rendered as
    // Stage 5 and as Stage 6's host-less path must produce identical hop
    // sentences, hop counts, and trace frames. No DNS hop, no cross-subnet
    // hop, 8 hops.
    const stage5Snap = { ...base(syncTrace), stage: 5, dns: null };
    const stage6Snap = base({ ...syncTrace, hosted: false, host: null });
    for (let hop = 1; hop <= 8; hop++) {
      const t5 = { ...syncTrace, hop };
      const t6 = { ...syncTrace, hop, hosted: false, host: null };
      expect(describeSnapshot({ ...base(t5), stage: 5, dns: null }).hopStatus).toBe(
        describeSnapshot({ ...base(t6) }).hopStatus,
      );
      expect(describeSnapshot({ ...base(t6) }).totalHops).toBe(8);
    }
    expect(describeSnapshot(stage6Snap).hop).toBe(6);

    // The engines agree too: same seed, same /about path, hop-for-hop
    // identical lastFrame strings across Stage 5 and Stage 6.
    const e5 = createEngine({ stage: 5 });
    const e6 = createEngine({ stage: 6 });
    const frames5 = [];
    const frames6 = [];
    for (let hop = 0; hop < 8; hop++) {
      e5.traceHop({ method: 'GET', path: '/about' });
      e6.traceHop({ method: 'GET', path: '/about' });
      frames5.push(e5.snapshot().lastFrame);
      frames6.push(e6.snapshot().lastFrame);
    }
    expect(frames6).toEqual(frames5);
    expect(e6.snapshot().dns).toMatchObject({ lookups: 0, cachedHits: 0, authoritative: 0 });
  });

  it('adds exactly two DNS hops to the hosted path — 10 hops with the ask and the answer', () => {
    const hostedTrace = {
      ...syncTrace,
      hop: 6,
      path: 'example.com/about',
      request: 'GET example.com/about',
      hosted: true,
      host: 'example.com',
      dnsTarget: '10.1',
      dnsStatus: 'MISS',
    };
    const labels = describeSnapshot(base(hostedTrace));
    expect(labels.totalHops).toBe(10);
    expect(labels.hopStatus).toBe('Hop 6/10: Database SELECT @ Replica (10.31) — fresh');

    const hopLabel = (hop, over = {}) =>
      describeSnapshot(base({ ...hostedTrace, hop, ...over })).hopStatus;
    expect(hopLabel(1)).toBe('Hop 1/10: Browser (10.2) emits "GET example.com/about"');
    expect(hopLabel(2)).toBe('Hop 2/10: Browser (10.2) asks DNS (10.60) — resolve example.com');
    expect(hopLabel(3)).toBe('DNS (10.60) -> 10.2 | example.com = 10.1 (authoritative)');
    expect(hopLabel(3, { dnsStatus: 'HIT' })).toBe(
      'DNS (10.60) -> 10.2 | example.com = 10.1 (cache HIT)',
    );
    // The served chain replays Stage 5's sentences at their shifted hops.
    expect(hopLabel(4)).toBe('Hop 4/10: Network (10.x) routes to LoadBalancer (10.1)');
    expect(hopLabel(5)).toBe('Hop 5/10: LoadBalancer (10.1) -> 10.11 queue');
    expect(hopLabel(7)).toBe('Hop 7/10: WebServer (10.11) -> "200 This is the about page" (cache MISS)');
    expect(hopLabel(9)).toBe('Hop 9/10: Browser (10.2) received and displayed 200');
    expect(hopLabel(10)).toBe('Hop 10/10: Worker (10.41) idle — no async jobs in this trace');
  });

  it('stops the NX path at the DNS answer after 3 hops — no GET is emitted', () => {
    const nxTrace = {
      ...syncTrace,
      hop: 3,
      path: 'nope.example/about',
      request: 'GET nope.example/about',
      hosted: true,
      host: 'nope.example',
      dnsTarget: null,
      dnsStatus: 'NX',
      cacheStatus: null,
      dbOp: null,
      response: 'NX no record',
      status: 'NX',
      body: 'no record',
      routeId: null,
      targetServer: null,
    };
    const labels = describeSnapshot(base(nxTrace));
    expect(labels.totalHops).toBe(3);
    const hopLabel = (hop) => describeSnapshot(base({ ...nxTrace, hop })).hopStatus;
    expect(hopLabel(1)).toBe('Hop 1/3: Browser (10.2) emits "GET nope.example/about"');
    expect(hopLabel(2)).toBe('Hop 2/3: Browser (10.2) asks DNS (10.60) — resolve nope.example');
    expect(hopLabel(3)).toBe('DNS (10.60) -> 10.2 | NX no record for nope.example');
    // The browser card renders the NX answer (status NX, body no record).
    expect(labels.browserStatus).toBe('NX (GET nope.example/about)');
    expect(labels.browserBody).toBe('no record');
  });

  it('mirrors the DNS ledger and Router counters in the inspector state', () => {
    const snap = base({
      ...syncTrace,
      hosted: true,
      host: 'example.com',
      dnsTarget: '10.1',
      dnsStatus: 'MISS',
    });
    const dnsState = JSON.parse(formatComponentState(snap, 'dns'));
    expect(dnsState).toEqual({
      address: '10.60',
      ttlTicks: 300,
      lookups: 1,
      cachedHits: 0,
      authoritative: 1,
      lastLookup: null,
      entries: [],
    });
    const routerState = JSON.parse(formatComponentState(snap, 'router'));
    expect(routerState).toEqual({ leftAddress: '10.65', rightAddress: '20.1', routed: 0 });
    const networkState = JSON.parse(formatComponentState(snap, 'network'));
    expect(networkState.interfaces['10.60']).toBe('DNS');
    expect(networkState.interfaces['10.65']).toBe('Router (10.x side)');
    expect(networkState.interfaces['20.1']).toBe('Router (20.x side)');
    expect(componentTitle(snap, 'dns')).toBe('DNS — mini-IP 10.60');
    expect(componentTitle(snap, 'router')).toBe('Router — 10.65 ⇄ 20.1');
  });

  it('lays out the 8-ring Stage 6 orrery with DNS on Ring 7 and the Router beside the 10.x hub', () => {
    const layout = computeStageLayout(6, 5);
    expect(layout.rings.map((r) => r.radius)).toEqual([
      400, 800, 1200, 1600, 2000, 2400, 2800, 3200,
    ]);
    expect(layout.rings.map((r) => r.id)).toEqual([
      'ring-db',
      'ring-workers',
      'ring-cache',
      'ring-compute',
      'ring-lb',
      'ring-network',
      'ring-dns',
